	'springform'   => [ 'intro' => 'Springforme med løs kant, så lagkager, cheesecakes og tærter slipper pænt. Find runde, firkantede og hjerteformede springforme fra de butikker, vi samarbejder med.' ],
	'muffinform'   => [ 'intro' => 'Muffinforme i metal og silikone til muffins, cupcakes og små tærter. Sammenlign udvalget fra de butikker, vi samarbejder med.' ],
	'pizzaspade'   => [ 'intro' => 'Pizzaspader i træ, aluminium og perforeret stål, der gør det let at skyde pizzaen ind og hente den ud igen. Se modellerne fra de butikker, vi samarbejder med.' ],
	'pizzaskaerer' => [ 'intro' => 'Pizzaskærere, pizzahjul og vippeknive, der deler pizzaen i rene stykker uden at trække osten med. Se udvalget fra de butikker, vi samarbejder med.' ],
	'kagerulle'    => [ 'intro' => 'Kageruller i træ, marmor og silikone til småkager, tærtedej og pizzabunde. Find den rette kagerulle blandt varerne fra de butikker, vi samarbejder med.' ],
	'haevekurv'    => [ 'intro' => 'Hævekurve, der giver surdejsbrødet form og et smukt mønster i skorpen. Se hævekurve i forskellige former fra de butikker, vi samarbejder med.' ],
	'sproejtepose' => [ 'intro' => 'Sprøjteposer og tyller til pynt på kager, cupcakes og desserter. Find engangsposer og poser til genbrug fra de butikker, vi samarbejder med.' ],
	'bageplade'    => [ 'intro' => 'Bageplader til småkager, boller og grøntsager i ovnen – med og uden slip-let-belægning. Se bagepladerne fra de butikker, vi samarbejder med.' ],

	// Kaffe & drikke.
	'elkedel'      => [ 'intro' => 'Elkedler, der koger vand på et øjeblik – fra enkle modeller til elkedler med temperaturvalg til te og kaffe. Sammenlign dem fra de butikker, vi samarbejder med.' ],
	'flaske-til-sodavandsmaskine' => [ 'intro' => 'Ekstra flasker til sodavandsmaskinen i plast, glas og stål, så der altid er en kold flaske klar. Tjek, at flasken passer til din maskine, og se udvalget fra de butikker, vi samarbejder med.' ],

	// Ovne & apparater.
	'indbygningsmikroovn' => [ 'intro' => 'Mikroovne til indbygning i køkkenskab eller overskab, så bordpladen holdes fri. Mål nichen og find en indbygningsmikroovn fra de butikker, vi samarbejder med.' ],
	'airfryer-tilbehoer'  => [ 'intro' => 'Tilbehør til airfryeren: forme, måtter, kurve, stativer og spyd, der gør den mere alsidig. Tjek målene på din kurv, og se udvalget fra de butikker, vi samarbejder med.' ],
	'multicooker'  => [ 'intro' => 'Multicookere, der kan trykkoge, langtidsstege, dampe og ofte også airfrye i én gryde. Sammenlign funktionerne på modellerne fra de butikker, vi samarbejder med.' ],
